/**
   * Extracts the sender, subject and message body from one Gmail trigger item.
   * Running once per item preserves n8n's item link when a poll returns several
   * stakeholder emails at the same time.
   */
  const email = $json;
  const headers = email.headers ?? {};

  const from = String(
    email.from ?? email.From ?? headers.from ?? headers.From ?? "",
  ).trim();
  const subject = String(
    email.subject ?? email.Subject ?? headers.subject ?? headers.Subject ?? "Untitled request",
  ).trim();
  const text = String(
    email.textPlain ?? email.text ?? email.snippet ?? email.Snippet ?? "",
  ).trim();
  const html = String(email.textHtml ?? email.html ?? email.Html ?? "")
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  const body = text || html || "No email body was provided.";
  const senderEmail = (from.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) ?? [""])[0];
  const senderName = from
    .replace(/<[^>]+>/g, "")
    .replace(senderEmail, "")
    .replace(/["<>]/g, "")
    .trim() || senderEmail || "External stakeholder";

  return {
    json: {
      messageId: email.id ?? email.messageId ?? "",
      threadId: email.threadId ?? "",
      senderName,
      senderEmail,
      subject,
      body,
      receivedAt: new Date().toISOString(),
    },
  };

/**
 * Reserves one of the ten daily automation slots for one email.
 * The counter follows the Europe/Berlin calendar day used by the public UI.
 */
const request = $json;
const data = $getWorkflowStaticData("global");
const today = getBerlinDateKey(new Date());
if (data.requestQuotaDate !== today) {
  data.requestQuotaDate = today;
  data.requestQuotaUsed = 0;
}
const used = Number(data.requestQuotaUsed ?? 0);
const dailyLimit = 10;
const limitReached = used >= dailyLimit;
if (!limitReached) data.requestQuotaUsed = used + 1;

return {
  json: {
    ...request,
    quota: {
      date: today,
      used: limitReached ? used : used + 1,
      dailyLimit,
      limitReached,
    },
  },
};

/**
 * Formats an instant as YYYY-MM-DD in the Europe/Berlin time zone.
 * @param {Date} date - Instant to format.
 * @returns {string} Berlin-local date key.
 */
function getBerlinDateKey(date) {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/Berlin",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const values = Object.fromEntries(parts.map(({ type, value }) => [type, value]));
  return `${values.year}-${values.month}-${values.day}`;
}

/**
   * Validates one AI result and converts it into a Join task and Firestore REST
   * payload. Throwing on malformed model output routes the linked email to the
   * existing manual-review branch instead of silently creating a fallback task.
   */
  const emailRequest = $("Extract email request").item.json;
  const aiOutput = $json.output ?? $json.text ?? $json;
  let parsed;

  try {
    parsed = typeof aiOutput === "string"
      ? JSON.parse(stripMarkdownCodeBlock(aiOutput))
      : aiOutput;
  } catch {
    throw new Error("AI response is not valid JSON.");
  }

  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("AI response must be a JSON object.");
  }

  const categories = new Set(["user-story", "technical-task"]);
  const priorities = new Set(["low", "medium", "urgent"]);
  const title = String(parsed.title ?? "").trim();
  const description = String(parsed.description ?? "").trim();
  const dueDate = parsed.dueDate;

  if (!title || !description) {
    throw new Error("AI response is missing a title or description.");
  }
  if (!categories.has(parsed.category) || !priorities.has(parsed.priority)) {
    throw new Error("AI response contains an unsupported category or priority.");
  }
  if (dueDate !== null && !isValidIsoDate(dueDate)) {
    throw new Error("AI response contains an invalid deadline.");
  }

  const fallbackDate = new Date(Date.now() + 7 * 86400000)
    .toISOString()
    .slice(0, 10);
  const task = {
    title: title.slice(0, 120),
    description: "[AI-generated from stakeholder email]\n\n" + description,
    dueDate: dueDate ?? fallbackDate,
    priority: parsed.priority,
    status: "triage",
    category: parsed.category,
    assignedTo: [],
    subtasks: [],
    source: "email",
    creator: {
      type: "external",
      name: emailRequest.senderName,
      email: emailRequest.senderEmail,
      uid: "",
    },
  };

  const firestoreDocument = {
    fields: {
      title: { stringValue: task.title },
      description: { stringValue: task.description },
      dueDate: { stringValue: task.dueDate },
      priority: { stringValue: task.priority },
      status: { stringValue: task.status },
      category: { stringValue: task.category },
      assignedTo: { arrayValue: { values: [] } },
      subtasks: { arrayValue: { values: [] } },
      source: { stringValue: task.source },
      creator: {
        mapValue: {
          fields: {
            type: { stringValue: task.creator.type },
            name: { stringValue: task.creator.name },
            email: { stringValue: task.creator.email },
            uid: { stringValue: task.creator.uid },
          },
        },
      },
      createdAt: { timestampValue: new Date().toISOString() },
      updatedAt: { timestampValue: new Date().toISOString() },
    },
  };

  return { json: { task, firestoreDocument, emailRequest } };

  /**
   * Removes Markdown code fences from an otherwise valid JSON response.
   * @param {string} value - Raw AI response.
   * @returns {string} JSON without surrounding Markdown fences.
   */
  function stripMarkdownCodeBlock(value) {
    return String(value)
      .trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();
  }

  /**
   * Checks both the format and calendar validity of an AI deadline.
   * @param {*} value - Candidate deadline.
   * @returns {boolean} Whether the value is a real YYYY-MM-DD date.
   */
  function isValidIsoDate(value) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value))) return false;
    const date = new Date(value + "T00:00:00Z");
    return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
  }
